import{z as s,x as d,o as e,c as B,q as l,j as o,D as i,d as r,s as n,S as E,b as t}from"./chunks/framework.C8m1ZpeB.js";const c=JSON.parse('{"title":"Roy 恒等式","description":"","frontmatter":{"title":"Roy 恒等式","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/roy-identity.md","filePath":"econ/roy-identity.md","lastUpdated":1791413859000}'),v={name:"econ/roy-identity.md"};function m(A,a,_,x,u,h){const p=d("Mermaid");return e(),B("div",null,[a[2]||(a[2]=l('<h1 id="roy-恒等式" tabindex="-1">Roy 恒等式 <a class="header-anchor" href="#roy-恒等式" aria-label="Permalink to &quot;Roy 恒等式&quot;">​</a></h1><div class="epigraph"><p>间接效用对价格的偏导，除以它对财富的偏导并改号，就是马歇尔需求。</p><footer>—— 据 Roy, La distribution du revenu entre les divers biens, Econometrica, 1947；Mas-Colell, Whinston and Green 第 3 章整理</footer></div><p>上一课<a href="/econ/indirect-utility">间接效用与支出函数</a>钉死了值函数 \\(v(p,w)\\) 与 \\(e(p,u)\\) 互逆。本课不重讲二者的定义，也不把支出最小化再写一遍。缺口是：间接效用对价格的导数如何恢复马歇尔需求。上一课把罗伊恒等式列为对偶接口；本课只把这一条公式钉成可操作的恢复。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>\\(v(p,w)=u\\bigl(x(p,w)\\bigr)\\) 是已经达到的效用。观测与计算里，有时更容易摸到 \\(v\\)——作为值函数、作为估计出的福利指标——而摸不到 \\(x\\) 的每一个坐标。缺口不是再解一次 \\(\\arg\\max\\)，而是从 \\(v\\) 的斜率读回选择。</p><p>Roy（1947）的恒等式说：在可微内点，</p> \\[x_i(p,w)=-\\frac{\\partial v/\\partial p_i}{\\partial v/\\partial w}. \\]<p>直观：涨 \\(p_i\\) 造成的效用损失，按财富的边际效用折成商品单位，就是必须减掉的 \\(x_i\\)。分母 \\(\\partial v/\\partial w\\) 在局部非饱和下为正，否则除法没有定义。本课不把希克斯需求拉进来；补偿需求是下一课的缺口。</p><p><span class="marginnote">直觉类比：\\(v(p,w)\\) 像一块「幸福仪表盘」。第 \\(i\\) 种商品涨价会让读数往下掉；把掉落的幅度除以「多给一块钱读数涨多少」，就换算出「相当于被拿走了几件商品 \\(i\\)」——这个件数正是你原本购买的数量 \\(x_i\\)。</span></p><h3 id="包络-不是把-再全微分" tabindex="-1">包络，不是把 \\(x\\) 再全微分 <a class="header-anchor" href="#包络-不是把-再全微分" aria-label="Permalink to &quot;包络，不是把 $x$ 再全微分&quot;">​</a></h3><p>\\(v\\) 随 \\(p\\) 变，有两条通道：最优束移动，以及同一束变得更贵。包络定理说，最优束移动的一阶贡献是零。剩下的是直接项 \\(-\\lambda x_i\\)，而 \\(\\lambda=\\partial v/\\partial w\\)。相除即得上式。不必把雅可比 \\(D_p x\\) 先求出来。</p><p><span class="marginnote">\\(v\\) 随 \\(u\\) 的单调变换而变，分子分母同乘一个正的变换导数，比值 \\(x_i\\) 不变。需求仍是序数对象。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>从拉格朗日 \\(u(x)+\\lambda(w-p\\cdot x)\\) 对参数求导，或从恒等式 \\(v(p,w)=u\\bigl(x(p,w)\\bigr)\\) 用包络。得到 \\(\\nabla_p v=-\\lambda x\\)，\\(\\partial v/\\partial w=\\lambda\\)。消去 \\(\\lambda\\) 即 Roy。零次齐次的 \\(v\\) 还给出欧拉关系：\\(\\sum_i p_i\\partial v/\\partial p_i+w\\partial v/\\partial w=0\\)，与瓦尔拉斯定律互证。</p><p><span class="marginnote">数字实例：设第 \\(i\\) 种商品涨价 1 元使 \\(v\\) 下跌 0.3 个单位，而多给 1 元使 \\(v\\) 上升 1.5 个单位，则 \\(x_i=-(-0.3)/1.5=0.2\\)——不必重新解最优化，两个斜率相除就把当前购买量读了出来。</span></p><p>经验上，若估计的是间接效用（或对数支出份额对价格的导数），Roy 把需求份额读出来，而不必先写 Marshallian 的闭式。本课不讨论估计，只锁定：对偶值函数的梯度就是需求的恢复。</p>',16)),(e(),o(E,null,{default:i(()=>[n(p,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20V%5B%22%E9%97%B4%E6%8E%A5%E6%95%88%E7%94%A8%20v(p%2Cw)%22%5D%20--%3E%20ENV%5B%22%E5%8C%85%E7%BB%9C%EF%BC%9A%E2%88%82v%2F%E2%88%82p%20%E4%B8%8E%20%E2%88%82v%2F%E2%88%82w%22%5D%0A%20%20ENV%20--%3E%20ROY%5B%22Roy%EF%BC%9Ax%20%3D%20-(%E2%88%82v%2F%E2%88%82p)%2F(%E2%88%82v%2F%E2%88%82w)%22%5D%0A%20%20ROY%20--%3E%20X%5B%22%E9%A9%AC%E6%AD%87%E5%B0%94%E9%9C%80%E6%B1%82%22%5D%0A%20%20X%20--%3E%20LATER%5B%22%E4%B8%8B%E4%B8%80%E8%AF%BE%EF%BC%9A%E5%B8%8C%E5%85%8B%E6%96%AF%E9%9C%80%E6%B1%82%22%5D%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t("p",null,"角点上 \\(v\\) 对某些 \\(p_i\\) 不可微，恒等式改成超梯度包含：\\(x\\) 属于 \\(-\\partial_p v\\big/\\partial_w v\\) 的对应。可微公式只在上一课说的正则内点用。",-1)),a[4]||(a[4]=t("h2",{id:"机制",tabindex:"-1"},[r("机制 "),t("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=t("p",null,"Roy 把「偏好 → 需求」的箭头在值函数上接了一段短路。不必每次改价格都重新求解 \\(\\arg\\max\\)；只要 \\(v\\) 可微，斜率比就是 \\(x\\)。这与谢泼德引理对称：那边从 \\(e\\) 读希克斯需求，这边从 \\(v\\) 读马歇尔需求。斯勒茨基分解要把两条需求焊在一起，所以两条导数接口都要。本课只交马歇尔这一头。",-1)),(e(),o(E,null,{default:i(()=>[n(p,{id:"mermaid-54",class:"mermaid",graph:"flowchart%20LR%0A%20%20V%5B%22%E5%80%BC%E5%87%BD%E6%95%B0%20v(p%2Cw)%22%5D%20--%3E%7C%22Roy%20%E6%81%92%E7%AD%89%E5%BC%8F%22%7C%20M%5B%22%E9%A9%AC%E6%AD%87%E5%B0%94%E9%9C%80%E6%B1%82%20x(p%2Cw)%22%5D%0A%20%20E%5B%22%E6%94%AF%E5%87%BA%E5%87%BD%E6%95%B0%20e(p%2Cu)%22%5D%20--%3E%7C%22%E8%B0%A2%E6%B3%BC%E5%BE%B7%E5%BC%95%E7%90%86%22%7C%20H%5B%22%E5%B8%8C%E5%85%8B%E6%96%AF%E9%9C%80%E6%B1%82%20h(p%2Cu)%22%5D%0A%20%20M%20--%3E%20SL%5B%22%E6%96%AF%E5%8B%92%E8%8C%A8%E5%9F%BA%E5%88%86%E8%A7%A3%E8%A6%81%E7%84%8A%E4%B8%A4%E6%9D%A1%E9%9C%80%E6%B1%82%22%5D%0A%20%20H%20--%3E%20SL%0A"})]),fallback:i(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=l('<p>福利语言里，\\(-\\partial v/\\partial p_i\\) 是涨价的效用损失，还不是钱。除以 \\(\\partial v/\\partial w\\) 才换成商品或货币单位。补偿变化仍用 \\(e\\) 来写，因为那是钱；Roy 不替代支出函数，只替代「从 \\(v\\) 找回 \\(x\\)」。</p><p><span class="marginnote">拟线性下 \\(\\partial v/\\partial w\\) 为常数（计价物内点），Roy 退化成 \\(x_i=-\\partial v/\\partial p_i\\) 的尺度。一般情形分母随 \\((p,w)\\) 变。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>恒等式要求 \\(v\\) 在所论的 \\((p,w)\\) 可微，需求单值。集值时只能写包含。价格为零或饱和使 \\(\\partial v/\\partial w=0\\)，公式停用——上一课的局部非饱和在这里是除法的前提。</p><p>也不要把 Roy 读成「观测到了间接效用」。观测仍是 \\((p,w,x)\\)；\\(v\\) 是模型对象。显示偏好课从 \\(x\\) 约束偏好，方向相反。本课仍走「已知 \\(v\\) → 读出 \\(x\\)」。</p><p><span class="marginnote">常见误区：Roy 的用途是「手上有 \\(v\\)（或估计好的支出份额方程）时读回需求」，不是宣称间接效用可以直接观测。能拿到的数据仍是价格、财富与购买量；\\(v\\) 永远是模型或估计的产物。</span></p><p>后课默认：可以随时用 Roy 从 \\(v\\) 恢复 \\(x(p,w)\\)。补偿需求 \\(h(p,u)\\) 下一课才作为独立对象出场。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>间接效用的价格斜率，按财富斜率折成商品，就是马歇尔需求。</li><li>依据是包络：最优束移动的一阶项消失。</li><li>角点改成超梯度；\\(\\partial v/\\partial w\\gt 0\\) 靠局部非饱和。</li><li>希克斯需求尚未作为本课对象。</li><li>出处：Roy, <em>Econometrica</em>, 1947；Mas-Colell, Whinston and Green 第 3 章。</li></ul>',9))])}const b=s(v,[["render",m]]);export{c as __pageData,b as default};
